function cast(sp){
  if(sp==='{g}')  return hero.guy;
  if(sp==='{P1}') return hero.p1;
  if(sp==='{P2}') return hero.p2;
  if(sp==='{F}')  return hero.f;
  return CAST[sp] || {key:'', emo:'💬', pitch:1, rate:1};
}

