// Бытовые сцены Насти встроены в сюжет (nastya_d_*). Сюда добавляют свои бытовые сцены остальные героини.
const FILL = [
];

// мужской персонаж? (имя в диалоге — синим)
function isMale(sp){
  if(sp==='{g}') return true;
  if(sp==='{P1}') return hero.p1.g==='m';
  if(sp==='{P2}') return hero.p2.g==='m';
  return !!(CAST[sp] && CAST[sp].m);
}
